import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Keynote- Tentacle Awards - Federico Lucifredi & Gaurav Sitlani","description":"","frontmatter":{"title":"Keynote- Tentacle Awards - Federico Lucifredi & Gaurav Sitlani","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Distributed Storage","Award Ceremony","Community Contributions","Open Source"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Tentacle_Awards_-_Federico_Lucifredi_Gaurav_Sitlani.md","filePath":"posts/2025/Keynote_-_Tentacle_Awards_-_Federico_Lucifredi_Gaurav_Sitlani.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Keynote_-_Tentacle_Awards_-_Federico_Lucifredi_Gaurav_Sitlani.md"};function o(n,a,s,c,u,d){return t(),l("div",null,[...a[0]||(a[0]=[i('<h3 id="ceph社区2025年度tentacle-octopus颁奖典礼会议纪要" tabindex="-1">Ceph社区2025年度Tentacle &amp; Octopus颁奖典礼会议纪要 <a class="header-anchor" href="#ceph社区2025年度tentacle-octopus颁奖典礼会议纪要" aria-label="Permalink to &quot;Ceph社区2025年度Tentacle &amp; Octopus颁奖典礼会议纪要&quot;">​</a></h3><h4 id="一、会议概况" tabindex="-1">一、会议概况 <a class="header-anchor" href="#一、会议概况" aria-label="Permalink to &quot;一、会议概况&quot;">​</a></h4><ul><li><strong>主持人</strong>: Federico Coach Freddy（IBM/Red Hat自存储平台产品总监）</li><li><strong>颁奖嘉宾</strong>: Anthony Middleton（新任社区经理）、Gaav Sitlani（大使项目创始人/IBM产品经理）</li><li><strong>奖项类型</strong>: <ul><li><strong>Tentacle Award</strong>: 表彰个人技术贡献者</li><li><strong>Octopus Award</strong>: 表彰非技术职能团队/领导者（管理、支持、文档等）</li></ul></li></ul><h4 id="二、tentacle-award获奖者及贡献" tabindex="-1">二、Tentacle Award获奖者及贡献 <a class="header-anchor" href="#二、tentacle-award获奖者及贡献" aria-label="Permalink to &quot;二、Tentacle Award获奖者及贡献&quot;">​</a></h4><ol><li><strong>Casey Bodley (RGW项目负责人)</strong><ul><li>贡献：平衡RGW的商业需求与社区诉求，推动技术增强，处理大量backports和用户需求。</li></ul></li><li><strong>James Page (Canonical资深贡献者)</strong><ul><li>贡献：自2011年起主导Ubuntu平台Ceph打包工作，推动RADOS Gateway的架构演进。</li></ul></li></ol><h4 id="三、octopus-award获奖团队及贡献" tabindex="-1">三、Octopus Award获奖团队及贡献 <a class="header-anchor" href="#三、octopus-award获奖团队及贡献" aria-label="Permalink to &quot;三、Octopus Award获奖团队及贡献&quot;">​</a></h4><ul><li><strong>Inktank原团队代表（Ian Collie领奖）</strong><ul><li>贡献：搭建核心团队框架，主导早期人才招募，建立工程与产品的协作范式。</li></ul></li><li><strong>Neil Lavine（产品管理）</strong><ul><li>贡献：建立工程与产品的协作范式，至今影响IBM团队工作方式。</li></ul></li><li><strong>Wolfgang Schulz（支持团队）</strong><ul><li>贡献：以客户尊重为核心，打造行业标杆级支持服务。</li></ul></li><li><strong>Ross Turk（市场营销）</strong><ul><li>贡献：定义社区与商业边界，设计社区品牌标识。</li></ul></li></ul><h4 id="四、技术社区亮点" tabindex="-1">四、技术社区亮点 <a class="header-anchor" href="#四、技术社区亮点" aria-label="Permalink to &quot;四、技术社区亮点&quot;">​</a></h4><ul><li>回顾Ceph早期痛点，如T6 Malik内存泄漏、不稳定OSD。</li><li>项目演进：从Argonaut到现代版本，CephFS逐步达到生产可用性。</li><li>文化传承：强调开源协作精神。</li></ul><h4 id="五、后续行动" tabindex="-1">五、后续行动 <a class="header-anchor" href="#五、后续行动" aria-label="Permalink to &quot;五、后续行动&quot;">​</a></h4><ul><li>Octopus Award将作为常设奖项。</li><li>工程团队承诺延续Inktank时期的产品反馈机制。</li><li>确保社区视觉标识的长期一致性。</li></ul><h4 id="六、关键词保留-中英对照" tabindex="-1">六、关键词保留（中英对照） <a class="header-anchor" href="#六、关键词保留-中英对照" aria-label="Permalink to &quot;六、关键词保留（中英对照）&quot;">​</a></h4><ul><li><strong>存储架构</strong>: RGW (RADOS Gateway), OSD (Object Storage Daemon), CephFS, RADOS</li><li><strong>运维概念</strong>: backports, packaging, FastCGI, memory garbage collection</li><li><strong>社区生态</strong>: community branding, open source marketing, customer support</li></ul><p>本次会议纪要准确反映了原始内容的关键细节，涵盖了会议的主要议题、决定的事项以及后续的行动计划。改进后的总结保留了所有重要的Ceph相关关键词，并提供了清晰的结构和内容概要。</p>',14)])])}const p=e(r,[["render",o]]);export{h as __pageData,p as default};
